import numpy as np, pandas as pd, xarray as xr
ds = xr.Dataset(
    {"air": (("time",), np.arange(4.0), {"long_name": "air temp", "units": "K"})},
    coords={"time": pd.date_range("2000-01-01", periods=4)},
)
ds.time.attrs = {"standard_name": "time", "long_name": "Time"}
res = xr.where(True, ds.air, ds.air, keep_attrs=True)
assert res.time.attrs == {"standard_name": "time", "long_name": "Time"}, res.time.attrs
assert res.attrs == {"long_name": "air temp", "units": "K"}
assert xr.where(True, ds.air, ds.air, keep_attrs=False).time.attrs == {}
dsd = xr.where(True, ds, ds, keep_attrs=True)
assert dsd.air.attrs == {"long_name": "air temp", "units": "K"}
assert dsd.time.attrs == {"standard_name": "time", "long_name": "Time"}
print("MVCE fixed: coord attrs preserved, var/global attrs kept, Dataset-level OK")
EOF
